import{renderDiagram}from './visual.js?v=20261022-eco6';import{productionFigure}from './eco6-figures.js?v=20261022-eco6';export function showEco6(spec='farming',w={}){let[kind,card]=spec.split(':');if(card==='1'&&kind==='farming'||card==='2'&&kind==='fisheries')kind+='-model';renderDiagram(w.title||'Compare production methods',w.label||'Original educational model',productionFigure({kind,state:card||'0',...w}),'ECOLOGY');}
